package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.util.DisplayMetrics;import java.util.*;
/** Bounds/interaction checks for one-row Apps toolbar and the padded six-item dock. */
public class ToolbarDockChecks extends Instrumentation {
 LauncherActivity a;int n;android.content.SharedPreferences prefs;Map<String,?> saved;Configuration original;DisplayMetrics metrics;
 void check(boolean b,String why){if(!b)throw new AssertionError(why);n++;}
 void ui(Runnable r){Throwable[] t={null};runOnMainSync(()->{try{r.run();}catch(Throwable e){t[0]=e;}});waitForIdleSync();if(t[0]!=null)throw new AssertionError(t[0]);}
 View find(View v,String name){if(name.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View hit=find(((ViewGroup)v).getChildAt(i),name);if(hit!=null)return hit;}return null;}
 boolean brand(View v){if(v instanceof TextView&&"iDash4".contentEquals(((TextView)v).getText()))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(brand(((ViewGroup)v).getChildAt(i)))return true;return false;}
 void force(View v){v.forceLayout();if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)force(((ViewGroup)v).getChildAt(i));}
 void layout(int w,int h){for(int pass=0;pass<2;pass++){force(a.stage);a.stage.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));a.stage.layout(0,0,w,h);}}
 void shot(String name,int w,int h){layout(w,h);Bitmap image=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);a.stage.draw(new Canvas(image));try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(a.getFilesDir(),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{image.recycle();}}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;try{
 prefs=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(prefs.getAll());prefs.edit().putBoolean("motion",false).putString("jakim_zone","SGR02").apply();a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(2);a.worker.execute(()->a.main.post(ready::countDown));a.networkWorker.execute(()->a.main.post(ready::countDown));check(ready.await(45,java.util.concurrent.TimeUnit.SECONDS),"data ready");original=new Configuration(a.getResources().getConfiguration());metrics=new DisplayMetrics();metrics.setTo(a.getResources().getDisplayMetrics());
 ui(()->{for(float font:new float[]{1,1.3f})for(int dock:new int[]{0,1})for(int[] size:new int[][]{{1024,600},{800,480}}){Configuration c=new Configuration(original);c.fontScale=font;DisplayMetrics dm=new DisplayMetrics();dm.setTo(metrics);dm.scaledDensity=dm.density*font;a.getResources().updateConfiguration(c,dm);prefs.edit().putInt("dock_size",dock).apply();a.page="apps";a.query="";a.render();layout(size[0],size[1]);View previous=null;Object parent=null;
 for(String name:new String[]{"Panel","Customize","Control Center","Search","Refresh","Done"}){View button=find(a.shell,name);check(button!=null&&button.getHeight()>=a.dp(48),"reachable 48dp toolbar target "+name);if(parent==null)parent=button.getParent();check(parent==button.getParent(),"one common toolbar row "+name);if(previous!=null)check(previous.getRight()<=button.getLeft(),"toolbar capsules separated");check(button.getLeft()>=0&&button.getRight()<=((View)button.getParent()).getWidth(),"toolbar stays within screen");previous=button;}
 check(!brand(a.shell),"brand label removed");ViewGroup bar=(ViewGroup)find(a.shell,"Launcher dock");int last=-1;
 for(int i=0;i<bar.getChildCount();i++){View child=bar.getChildAt(i);if(!(child instanceof LinearLayout))continue;ViewGroup tile=(ViewGroup)child;View icon=tile.getChildAt(0),label=tile.getChildAt(1);check(tile.getTop()+icon.getTop()>=a.dp(8),"icon clears capsule top");check(tile.getBottom()<=bar.getHeight()-a.dp(8),"tile clears capsule bottom");check(child.getLeft()>=last,"dock items separated");check(icon.getBottom()<=label.getTop()&&label.getBottom()<=tile.getHeight(),"dock label and icon fit");last=child.getRight();}
 if(dock==0&&font==1)shot("toolbar-apps-"+size[0]+"x"+size[1],size[0],size[1]);}
 a.getResources().updateConfiguration(original,metrics);prefs.edit().putInt("dock_size",0).apply();a.page="apps";a.render();find(a.shell,"Search").performClick();check(a.search.getVisibility()==View.VISIBLE,"Search opens field");a.search.setText("no-app-8765432");check(find(a.grid,"No app results")!=null,"filter works");find(a.shell,"Search").performClick();check(a.search.getVisibility()==View.GONE&&a.query.isEmpty(),"Search toggles off and resets filter");find(a.shell,"Done").performClick();check("home".equals(a.page),"Done returns Home");prefs.edit().putInt("panel_mode",1).apply();a.panelVisible=true;a.render();shot("home-panel-1024x600",1024,600);check(!brand(a.shell),"Home brand removed");});
 out.putString("stream","PASS: "+n+" toolbar/dock assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+n+": "+t+"\n");}finally{if(a!=null)ui(()->{if(original!=null)a.getResources().updateConfiguration(original,metrics);a.finish();});if(prefs!=null&&saved!=null)AppearanceChecks.restore(prefs,saved);}finish(code,out);}
}
